G=(32,0);
H=(16,0);
W=origin;
X=(0,36);
Y=(48,36);
Z=(48,0);
filldraw(W--A--H--cycle^^B--X--C--cycle^^D--Y--E--cycle^^F--Z--G--cycle,rgb(.76,.76,.76));
draw(W--X--Y--Z--cycle,linewidth(1.2));
dot(A);
dot(B);
dot(C);
dot(D);
dot(E);
