pair A = (0,0);
pair temp = (1,0);
pair B = rotate(45,A)*temp;
pair C = rotate(90,B)*A;
pair D = rotate(270,C)*B;
pair E = rotate(270,D)*C;
pair F = rotate(90,E)*D;
pair G = rotate(270,F)*E;
